#include "../build_config.h"
// Crusaders Mainframe — RSA-2048 signature verification (RSASSA-PKCS1-v1_5,
// SHA-256, e = 65537), for signed OTA on both ESP chips.
//
// WHY RSA, AND WHY HERE
// ---------------------
// Device contract v3 (docs/specs/device-api.md §7) makes the next USB flash the
// last one, so both ESP images must be able to take a new image over WiFi — and
// must refuse any image the founder did not sign. A public-key VERIFY with
// e = 65537 is seventeen modular multiplications and nothing else: no key
// generation, no secret, no random number. Written once, here, it is the SAME
// bytes on the ESP8266 bridge, the ESP32 door and the host test runner, so one
// implementation is checked against `ota/cases.json` everywhere. ECDSA would
// have meant BearSSL on one chip and mbedTLS on the other, tested twice.
//
// STRICT BY CONSTRUCTION
// ----------------------
// The decrypted block is compared WHOLE against the one encoding PKCS#1 v1.5
// allows for this digest — `00 01 FF…FF 00 <DigestInfo(SHA-256)> <digest>`.
// Nothing is parsed out of it. Every historical PKCS#1 v1.5 forgery (Bleichen-
// bacher 2006 and its descendants) lives in a verifier that PARSED the ASN.1 and
// accepted trailing garbage or a short padding run; a verifier that rebuilds
// the expected block and compares all 256 bytes has no parser to fool.
//
// MEMORY
// ------
// Montgomery multiplication over 32-bit limbs, everything on the stack: about
// 1.6 KB at the deepest point, no heap, no recursion, no static state. That
// fits the ESP8266's 4 KB continuation stack with the caller's frame on top;
// the ESP32's loop task has 8 KB.
//
// Valid C++11 as well as C++17: both generated sketches build at gnu++11.
// No Arduino headers. Compiles for AVR, Xtensa and the host.

#ifndef CRUSADERS_DEVCRYPTO_RSA_H
#define CRUSADERS_DEVCRYPTO_RSA_H

#include <stddef.h>
#include <stdint.h>

namespace dc {

/// Modulus and signature length of RSA-2048, in bytes (big-endian, as on the
/// wire and in the corpus).
inline constexpr size_t kRsa2048Bytes = 256U;

/// The public exponent this verifier supports, and the only one: the founder's
/// key is generated with it (`src/iot/tools/ota_sign.py keygen`).
inline constexpr uint32_t kRsaPublicExponent = 65537UL;

/// True when `signature`, read as a big-endian integer, is strictly less than
/// `modulus`. A signature at or above the modulus is refused BEFORE any
/// exponentiation (`ota/` `sig-out-of-range`): it is not a value the private
/// key could have produced.
bool rsa2048InRange(const uint8_t modulus[kRsa2048Bytes], const uint8_t signature[kRsa2048Bytes]);

/// `input^65537 mod modulus`, big-endian in and out. False — `out` untouched —
/// when the modulus is even or has a zero top byte (not an RSA-2048 modulus at
/// all) or when `input` is not below it.
bool rsa2048PublicOp(const uint8_t modulus[kRsa2048Bytes], const uint8_t input[kRsa2048Bytes],
                     uint8_t out[kRsa2048Bytes]);

/// RSASSA-PKCS1-v1_5 verification of a SHA-256 `digest` under `modulus`
/// (e = 65537). True only when `signature` is in range and its public operation
/// equals, byte for byte, the one encoding of `digest` the scheme allows.
bool rsa2048VerifySha256(const uint8_t modulus[kRsa2048Bytes], const uint8_t digest[32],
                         const uint8_t signature[kRsa2048Bytes]);

} // namespace dc

/// The name the device contract's brief uses for this library. The rest of
/// devcrypto has always lived in `dc`; both spellings reach the same functions.
namespace devcrypto = dc;

#endif // CRUSADERS_DEVCRYPTO_RSA_H
